DECLARE @a int,@s binary(8);SELECT TOP(1) @a=MaTK,@s=SecurityStamp FROM dbo.TAIKHOAN WHERE MaVT='ADMIN' AND HoatDong=1 ORDER BY MaTK;IF (SELECT DiemTichLuy FROM dbo.KHACHHANG WHERE MaKH='KH020')<>0 OR EXISTS(SELECT 1 FROM dbo.CustomerOpening WHERE MaKH='KH020') OR EXISTS(SELECT 1 FROM dbo.G03OperationReceipt WHERE RequestId='11111111-1111-1111-1111-111111111112') THROW 52999,'Customer partial state',1;
